def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, max(8.0, DAILY_SALARY * 0.22)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    tight_supply = supply <= 18.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if tight_supply:
        danger += 1
    if urgent_opp >= 2:
        danger += 1

    if danger >= 5:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.5)
    elif danger >= 3:
        bid = max(DAILY_SALARY * 0.78, highest_prev + 1.2)
    else:
        if highest_prev >= DAILY_SALARY * 1.35:
            bid = DAILY_SALARY * 0.24 if hp > 4 and no_water_days == 0 else DAILY_SALARY * 0.9
        elif highest_prev >= DAILY_SALARY * 1.05:
            bid = DAILY_SALARY * (0.34 if hp > 5 and no_water_days == 0 else 0.74)
        elif highest_prev >= DAILY_SALARY * 0.75:
            bid = max(DAILY_SALARY * 0.52, avg_prev + 1.0)
        elif highest_prev > 0:
            bid = max(DAILY_SALARY * 0.42, highest_prev + 1.5)
        else:
            bid = DAILY_SALARY * 0.45

    if rich_opp >= 2 and not tight_supply and danger <= 2:
        bid *= 0.92
    if tight_supply and danger >= 2:
        bid *= 1.08
    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.94

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = DAILY_SALARY * 0.35
    elif hp > 2:
        reserve = DAILY_SALARY * 0.18

    cap = max(0.0, budget - reserve)
    if danger >= 4:
        cap = budget

    bid = min(bid, cap if cap > 0 else budget)
    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1) 

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Aggressive bidding if HP is critical
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # More aggressive if HP is low
    if my_status['hp'] <= 5:
        # If strong bids yesterday, try to outbid
        if highest_prev_bid >= DAILY_SALARY * 0.8: # Consider a high bid from yesterday as a threat
            return min(my_status['budget'], highest_prev_bid + 5)
        # Otherwise, bid firmly
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    # HP is good, conserve budget but stay competitive
    # If there were high bids yesterday
    if highest_prev_bid >= DAILY_SALARY * 0.7: # Moderate threat level
        # If supply is low (only 1 winner possible for my water_req)
        if day_context['supply'] < WATER_REQ * 2: 
            return min(my_status['budget'], max(DAILY_SALARY * 0.75, highest_prev_bid + 2))
        # If supply is ample (2 winners possible for my water_req)
        return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid * 0.95)) # Bid slightly less than their high but still competitive

    # HP is good, and no significant high bids from opponents yesterday
    return min(my_status['budget'], DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents and yesterday bid signals
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        # No opponents alive: spend to ensure survival
        target = DAILY_SALARY * 0.35
        return float(min(my_status['budget'], max(0.0, target)))

    yesterday_bids = []
    yesterday_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                yesterday_hp_after.append(float(prev['hp_after']))
            except Exception:
                pass

    # Estimate opponent aggression from yesterday
    if yesterday_bids:
        # Use median to avoid outliers (like Eric)
        sorted_bids = sorted(yesterday_bids)
        n = len(sorted_bids)
        mid_idx = int(n // 2)
        if n % 2 == 1:
            median_bid = sorted_bids[mid_idx]
        else:
            median_bid = 0.5 * (sorted_bids[int(mid_idx - 1)] + sorted_bids[int(mid_idx)])
        max_prev_bid = max(yesterday_bids)
    else:
        median_bid = DAILY_SALARY * 0.55
        max_prev_bid = DAILY_SALARY * 0.85

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Supply pressure heuristic: higher supply reduces need to overbid.
    # With supply in [15,25], water likely enough for 1 requirement unit.
    supply_level = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_level = max(0.0, min(1.0, supply_level))

    # Base bid to beat the common aggressive baseline.
    # If my hp is low, bid more to avoid elimination.
    if my_hp <= 2.0:
        urgency_mult = 0.95
    elif my_hp <= 4.0:
        urgency_mult = 0.75
    else:
        urgency_mult = 0.60

    # If yesterday showed very high bids, slightly overtake.
    # Otherwise, bid just above median.
    if max_prev_bid >= DAILY_SALARY * 0.85:
        target_bid = median_bid + 6.0
        target_bid = min(target_bid, max_prev_bid + 2.0)
    else:
        target_bid = median_bid + 3.0

    # Adjust for supply: when supply is higher, reduce bid a bit.
    target_bid *= (1.0 - 0.15 * supply_level)

    # Cap by urgency and budget
    # Ensure we don't bid more than we can afford.
    budget_cap = my_budget

    # Also keep a minimum bid if we need water soon
    no_water_days = int(my_status.get('no_water_days', 0) or 0)
    if no_water_days >= 2:
        target_bid = max(target_bid, DAILY_SALARY * 0.70)

    # Final decision
    final_bid = min(budget_cap, max(0.0, target_bid * urgency_mult))

    # If budget is extremely low, still attempt survival with whatever remains.
    if final_bid <= 0.0:
        final_bid = min(budget_cap, DAILY_SALARY * 0.2)

    return float(final_bid)
